-- 114: biblioteca de exemplos do pico, por tipo de peça. Global, serve a todos os picos.
create table if not exists pico_biblioteca (
  id uuid primary key default gen_random_uuid(),
  categoria text not null, titulo text not null, url text, tipo text, nota text, fonte text,
  ordem integer not null default 0, criado_em timestamptz not null default now());
alter table pico_biblioteca enable row level security;
drop policy if exists pico_biblioteca_auth on pico_biblioteca;
create policy pico_biblioteca_auth on pico_biblioteca for all to authenticated using (true) with check (true);
delete from pico_biblioteca where fonte in ('Playbook Black Friday','Retiro Black Friday','Ultra Retiro','Playbook mid ticket');
